describe('CodexStreamingAdapter', () => {
    it('dismisses Codex questions with a valid empty answers map', async () => {
        const { adapter, writes } = harness('codex');
        const questions = [{ header: 'Confirm', id: 'confirm', question: 'Proceed?' }];

        await adapter.handleMessage({ id: 99, method: 'item/tool/requestUserInput', params: { questions } });
        await adapter.dismissQuestion(99);

        expect(writes).toContainEqual({ id: 99, result: { answers: {} } });
        await expect(adapter.answerQuestion(99, { confirm: ['Yes'] }))
            .rejects.toThrow('Unknown or stale Codex question request id');
    });

    it('initializes, starts one thread, then starts and steers a turn', async () => {
        const { adapter, events, writes } = harness('codex');

        await adapter.start('plan');
        expect(writes[0]).toMatchObject({ id: 1, method: 'initialize' });
        await adapter.handleMessage({ id: 1, result: { userAgent: 'codex' } });
        expect(writes[1]).toEqual({ method: 'initialized', params: {} });
        expect(writes[2]).toMatchObject({ id: 2, method: 'account/rateLimits/read' });
        expect(writes[3]).toMatchObject({ id: 3, method: 'thread/start', params: { cwd: 'C:\\repo' } });
        await adapter.handleMessage({ id: 3, result: { thread: { id: 'thread-1' } } });
        expect(writes[4]).toMatchObject({
            method: 'turn/start',
            params: { input: [{ text: 'plan', type: 'text' }], threadId: 'thread-1' },
        });
        await adapter.handleMessage({
            method: 'turn/started',
            params: { threadId: 'thread-1', turn: { id: 'turn-1' }, turnId: 'turn-1' },
        });
        await adapter.sendMessage('extra detail');
        expect(writes[5]).toMatchObject({
            method: 'turn/steer',
            params: {
                expectedTurnId: 'turn-1',
                input: [{ text: 'extra detail', type: 'text' }],
                threadId: 'thread-1',
            },
        });
        expect(events).toContainEqual({ conversationId: 'thread-1', type: 'sessionStarted' });
    });

    it.each([
        [null, 'priority', 'thread/start'],
        ['saved-thread', 'default', 'thread/resume'],
    ])('applies explicit model, effort and tier on %s and every new turn', async (sessionId, serviceTier, method) => {
        const settings = { model: 'gpt-6.1-sol', effort: 'xhigh', serviceTier };
        const { adapter, writes } = harness('codex', sessionId, settings);
        await adapter.start('first prompt');
        await adapter.handleMessage({ id: 1, result: {} });
        expect(writes[3]).toMatchObject({method, params: {model: 'gpt-6.1-sol', serviceTier, config: { model_reasoning_effort: 'xhigh' }}});
        await adapter.handleMessage({ id: 3, result: { thread: { id: 'saved-thread' }, model: 'gpt-6.1-sol', serviceTier } });
        expect(writes[4]).toMatchObject({ method: 'turn/start', params: settings });
        expect(adapter.resolvedSettings).toEqual({ model: 'gpt-6.1-sol', serviceTier });
        await adapter.sendMessage('second prompt');
        expect(writes[5]).toMatchObject({ method: 'turn/start', params: settings });
    });

    it.each(['default', undefined])('refuses to infer when the requested Fast tier is not acknowledged: %s', async (serviceTier) => {
        const { adapter, events, writes } = harness('codex', null, { model: 'gpt-6.1-sol', serviceTier: 'priority' });
        await adapter.start('prompt');
        await adapter.handleMessage({ id: 1, result: {} });
        await adapter.handleMessage({ id: 3, result: { thread: { id: 'thread' }, model: 'gpt-6.1-sol', serviceTier } });
        expect(events).toContainEqual(expect.objectContaining({ type: 'fatal', content: expect.stringContaining('did not acknowledge') }));
        expect(writes.some(({ method }) => method === 'turn/start')).toBe(false);
    });

    it('publishes initial, updated, and unavailable account rate-limit runtime events', async () => {
        const { adapter, runtimeEvents } = harness('codex');
        const rateLimits = {
            credits: null,
            individualLimit: null,
            limitId: 'codex',
            limitName: 'Codex',
            planType: 'plus',
            primary: { resetsAt: 100, usedPercent: 20, windowDurationMins: 300 },
            rateLimitReachedType: null,
            secondary: null,
        };

        await adapter.start('plan');
        await adapter.handleMessage({ id: 1, result: {} });
        await adapter.handleMessage({
            id: 2,
            result: { rateLimitResetCredits: null, rateLimits, rateLimitsByLimitId: null },
        });
        await adapter.handleMessage({
            method: 'account/rateLimits/updated',
            params: { rateLimits: { ...rateLimits, primary: { ...rateLimits.primary, usedPercent: 30 } } },
        });

import { createRequire } from 'node:module';
import { describe, expect, it, vi } from 'vitest';

const require = createRequire(import.meta.url);
const { resolveAgentExecution } = require('./agent_execution');
const { AgentModelCatalogService } = require('./agent_model_catalog_service');
const { BUILTIN_AGENT_PROFILES, buildResumeAgentCommand } = require('./agent_profiles.mjs');

function config(speedMode) {
    const profile = { ...BUILTIN_AGENT_PROFILES.find(({ name }) => name === 'codex'), defaultModel: 'gpt-6.1-sol' };

    return {
        agentTaskTrackingEnabled: false,
        agentProfiles: [profile],
        agentSelection: {
            activeAgent: 'codex', permissionMode: 'ask-for-approval',
            settingsByAgent: { codex: { model: 'gpt-6.1-sol', thinkingLevel: 'max', speedMode } },
        },
    };
}

describe('agent execution settings', () => {
    it.each([false, true])('prepares selected settings without reading model lists when streaming is %s', (streaming) => {
        const loadCatalog = vi.spyOn(AgentModelCatalogService.prototype, 'load').mockRejectedValue(new Error('Catalog unavailable'));
        try {
            const resolved = resolveAgentExecution(config('fast'), { model: 'new-model', thinkingLevel: 'high' }, streaming);

            expect(resolved.executionSettings).toEqual({ model: 'new-model', effort: 'high', serviceTier: 'priority' });
            expect(loadCatalog).not.toHaveBeenCalled();
        } finally {
            loadCatalog.mockRestore();
        }
    });

    it('applies Fast settings and retains them during one-shot resume', () => {
        const resolved = resolveAgentExecution(config('fast'), {}, false);
        expect(resolved.agentTaskTrackingEnabled).toBe(false);
        expect(resolved.command).toContain('tools.update_plan.enabled=false');
        expect(resolved.command).toContain('service_tier="priority"');
        expect(resolved.command).toContain('features.fast_mode=true');
        expect(resolved.executionSettings).toEqual({ model: 'gpt-6.1-sol', effort: 'xhigh', serviceTier: 'priority' });
        const resumed = buildResumeAgentCommand(resolved.profile, 'saved-session', resolved.command);
        expect(resumed).toContain('service_tier="priority"');
        expect(resumed.slice(-4)).toEqual(['exec', 'resume', '--json', 'saved-session']);
    });

    it('explicitly clears Fast for Standard and leaves provider default unoverridden', () => {
        const standard = resolveAgentExecution(config('standard'), {}, true);
        expect(standard.executionSettings.serviceTier).toBe('default');
        expect(standard.command).toContain('service_tier="default"');
        const inherited = resolveAgentExecution(config('default'), {}, true);
        expect(inherited.executionSettings).not.toHaveProperty('serviceTier');
        expect(inherited.command.some((value) => value.startsWith('service_tier='))).toBe(false);
    });

    it('preserves a selected model without adding a reasoning override for none', () => {
        const resolved = resolveAgentExecution(config('default'), { model: 'new-model', thinkingLevel: 'none' }, true);

        expect(resolved.executionSettings).toEqual({ model: 'new-model' });
    });
});

